import {closeMobileSidebar} from './sidebar.js';
import {requestJSON} from './api-client.js';
import {csvCell} from './csv-guard.js';
import {primaryImage,imageScopeLabel,isProductImage,imageScope} from './image-policy.js';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const txt=v=>v==null?'':typeof v==='string'?v:JSON.stringify(v);
const clone=v=>JSON.parse(JSON.stringify(v));
const list=v=>Array.isArray(v)?v:[];
const splitTags=v=>[...new Set(String(v||'').split(/[\n,，、;；]/).map(s=>s.trim()).filter(Boolean))];
const viewNames={records:'产品资料',taxonomy:'分类与检索标签',settings:'网站内容',samples:'实物样品',plans:'选型方案',users:'员工与权限',imports:'批量导入与导出',audit:'修改记录'};
const kindNames={package:'包材',source_page:'图册与图片线索',process_rule:'工艺与价格参考',semi_finished:'料体与半成品',service:'检测与服务',requirement:'需求资料',uncertain:'待分类'};
const userRoleNames={employee:'员工',admin:'管理员',client:'客户展示'};
const statusNames={available:'在库可借',lent:'已借出',consumed:'测试耗用',sent:'已寄给客户'};
const resourceNames={records:'产品',settings:'网站内容',taxonomy:'分类标签',samples:'实物样品',plans:'选型方案',users:'员工账号'};
const actionNames={product_cleanup_archive:'无图产品归档',product_details_enrich:'整理产品细则',brand_refresh:'产品整理与界面更新',initial:'初始资料',password_reset:'重置密码',admin_save:'管理员修订',admin_archive:'管理员归档',admin_unarchive:'管理员恢复',save:'保存',create:'新建',update:'修改',archive:'归档',unarchive:'恢复归档',restore:'恢复版本',import:'导入',import_create:'导入新建',import_update:'导入更新'};
const rawLabels={addressRaw:'供应商地址',extra2Raw:'其他补充',requirementsRaw:'需求说明',testPlanRaw:'测试计划',materialRaw:'材质说明',specificationRaw:'规格说明',quoteRaw:'采购单价／普通报价',moqRaw:'普通起订量 MOQ',leadTimeRaw:'普通货期',customQuoteRaw:'定制报价',customMoqRaw:'定制起订量',customLeadTimeRaw:'定制货期',supplierRaw:'供应商名称',contactRaw:'供应商联系方式／联系人',processRaw:'工艺说明（历史原文）',remarksRaw:'备注',customerRaw:'客户／需求来源',sampleFeeRaw:'样品费用',moldFeeRaw:'开模费用',dateOrNotesRaw:'询价日期与原备注',extraRaw:'其他信息'};
const fieldNames={name:'产品名称',kind:'资料类型',category:'包材分类',bottleType:'瓶型',materials:'标准材质',capacityMl:'容量 mL',uses:'用途标签',series:'系列',model:'款式／型号',description:'产品说明',quoteHeader:'报价口径',currency:'币种',unitPrice:'确认单价',validUntil:'报价有效期',sourceNote:'来源补充',images:'产品图片',productDetails:'产品细则',uncertainties:'待确认事项',archived:'归档状态',title:'名称',note:'备注',location:'存放位置',condition:'样品状况',status:'样品状态',borrower:'借用人',due:'预计归还',role:'权限',active:'启用状态',...rawLabels};
let session={},cache={records:[],users:[],samples:[],plans:[],audit:[],settings:{value:{},version:0},taxonomy:{value:{},version:0}},editor=null,viewSequence=0,toastTimer,indexTimer;
const state={view:'records',query:'',showArchived:false,kind:'',page:1,mainDirty:false,busy:false,index:null,importPreview:null,importName:'',importBusy:false,auditResource:''};

async function api(path,data){
  const options={timeoutMs:path==='/api/admin/records'?60000:30000};
  options.headers={};
  if(data!==undefined){options.method='POST';options.headers['Content-Type']='application/json';options.headers['X-CSRF-Token']=session.csrf||'';options.body=JSON.stringify(data);}
  return requestJSON(path,options);
}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').style.display='block';toastTimer=setTimeout(()=>{$('#toast').style.display='none';},4500);}
function errorText(error){return error.status===409?'这条资料已被其他操作更新。你的输入仍保留，请复制需要保留的内容，关闭后重新打开最新资料，再合并修改。':error.status===401?'登录已过期。你的输入仍保留，请在新窗口重新登录后再保存。':error.message;}
function setFormError(form,error){const el=form.querySelector('[data-form-status]');if(el){el.textContent=errorText(error);el.classList.add('error');}else toast(errorText(error));}
function dateLabel(value){if(!value)return '—';const d=new Date(value);return Number.isNaN(d.getTime())?String(value):d.toLocaleString('zh-CN',{hour12:false});}
function imageURL(image){const raw=String(image?.path||image?.file||'').replace(/\\/g,'/').replace(/^\/+/,'');const upload=raw.startsWith('uploads/');const parts=raw.replace(/^uploads\//,'').replace(/^media\//,'').split('/').filter(x=>x&&x!=='.'&&x!=='..');return (upload?'/uploads/':'/media/')+parts.map(encodeURIComponent).join('/');}
function usableImage(record){return primaryImage(record);}
function thumbnail(record){const image=usableImage(record);return image?`<img class="admin-thumb" src="${esc(imageURL(image))}" alt="${esc(record.name||'产品图片')}" loading="lazy"><small class="image-scope-note">${esc(imageScopeLabel(image,record))}</small>`:'<span class="thumb-empty">单品图待整理</span>';}
function short(value,n=65){const s=txt(value);return s.length>n?s.slice(0,n)+'…':s;}
function searchText(item){return Object.entries(item).filter(([k])=>!['rawCells','provenance','images','snapshot','before','after','searchText'].includes(k)).map(([,v])=>txt(v)).join(' ').toLowerCase();}
function normalizeProductCode(value){const compact=String(value??'').normalize('NFKC').toUpperCase().replace(/[\s\u200b\u200c\u200d\ufeff\-‐‑‒–—−﹘﹣]/gu,'');const match=/^YZBC(\d{6,})$/.exec(compact);return match?'YZ-BC-'+match[1]:null;}
function visibleItems(resource){let items=list(cache[resource]);if(['records','samples','plans'].includes(resource)&&!state.showArchived)items=items.filter(i=>!i.archived);if(resource==='records'&&state.kind)items=items.filter(i=>i.kind===state.kind);const code=resource==='records'?normalizeProductCode(state.query):null;if(code)return items.filter(i=>normalizeProductCode(i.productCode)===code);const q=state.query.trim().toLowerCase();if(q)items=items.filter(i=>searchText(i).includes(q));return items;}
function pageSlice(items){const pages=Math.max(1,Math.ceil(items.length/20));state.page=Math.max(1,Math.min(state.page,pages));return {rows:items.slice((state.page-1)*20,state.page*20),pages};}
function numberedPages(current,pages){if(pages<=7)return Array.from({length:pages},(_,i)=>i+1);const values=new Set([1,pages,current-1,current,current+1]);if(current<=3)[2,3,4].forEach(p=>values.add(p));if(current>=pages-2)[pages-3,pages-2,pages-1].forEach(p=>values.add(p));const sorted=[...values].filter(p=>p>=1&&p<=pages).sort((a,b)=>a-b),result=[];for(const p of sorted){if(result.length&&p-result[result.length-1]>1)result.push('gap');result.push(p);}return result;}
function pagination(total,pages){const start=total?(state.page-1)*20+1:0,end=Math.min(state.page*20,total);return `<div class="admin-pagination" role="navigation" aria-label="${esc(viewNames[state.view]||'列表')}分页" data-pages="${pages}" data-total="${total}"><div class="admin-page-summary" id="adminPageStatus" role="status" aria-live="polite" aria-atomic="true">第 ${state.page} / ${pages} 页 · 显示 ${start}–${end} 条，共 ${total} 条</div><div class="admin-page-controls"><button type="button" class="btn small" data-page="${state.page-1}" ${state.page<=1?'disabled':''}>上一页</button><div class="admin-page-numbers">${numberedPages(state.page,pages).map(p=>p==='gap'?'<span class="admin-page-gap" aria-hidden="true">…</span>':`<button type="button" class="btn small admin-page-number ${p===state.page?'is-current':''}" data-page="${p}" aria-label="第 ${p} 页" ${p===state.page?'aria-current="page"':''}>${p}</button>`).join('')}</div><button type="button" class="btn small" data-page="${state.page+1}" ${state.page>=pages?'disabled':''}>下一页</button></div><form id="adminPageJumpForm" class="admin-page-jump" novalidate><label for="adminJumpPage">跳至</label><input id="adminJumpPage" name="page" type="number" inputmode="numeric" min="1" max="${pages}" step="1" value="${state.page}" aria-label="跳转页码" aria-describedby="adminPageError"><span>页</span><button class="btn small" type="submit">跳转</button></form><span id="adminPageError" class="admin-page-error" role="alert"></span></div>`;}
function pageJumpError(message){const error=$('#adminPageError'),input=$('#adminJumpPage');if(error)error.textContent=message;if(input){input.setAttribute('aria-invalid','true');input.focus();}}
function goToPage(value,fromJump=false){if(state.busy||state.mainDirty||editor?.busy||editor?.dirty||$('#adminDialog').open)return;const pager=$('.admin-pagination');if(!pager)return;const numeric=Number(String(value).trim()),pages=Number(pager.dataset.pages);if(String(value).trim()===''||!Number.isSafeInteger(numeric)){pageJumpError('请输入整数页码。');return;}const target=Math.max(1,Math.min(pages,numeric)),adjusted=target!==numeric;if(target===state.page){const input=$('#adminJumpPage');if(input){input.value=String(target);input.removeAttribute('aria-invalid');}$('#adminPageError').textContent='';if(adjusted)$('#adminPageStatus').textContent=`已调整至第 ${target} 页；有效范围为 1–${pages} 页。`;return;}state.page=target;const renderer={records:renderRecords,samples:renderSamples,plans:renderPlans,users:renderUsers,audit:renderAudit}[state.view];if(!renderer)return;const template=document.createElement('template');template.innerHTML=renderer();const oldResults=$('#main .table-wrap'),newResults=template.content.querySelector('.table-wrap'),newPager=template.content.querySelector('.admin-pagination');if(!oldResults||!newResults||!newPager)return;oldResults.replaceWith(newResults);pager.replaceWith(newPager);if(adjusted)$('#adminPageStatus').textContent+=`；页码已调整至 ${target}。`;const reduced=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduced)newResults.classList.add('admin-page-results-enter');const focus=fromJump?$('#adminJumpPage'):newPager.querySelector('[aria-current="page"]');focus?.focus({preventScroll:true});if(fromJump)focus?.select();newResults.scrollIntoView?.({block:'start',behavior:reduced?'auto':'smooth'});}
function head(title,sub,buttons=''){return `<div class="head"><div><div class="eyebrow">YUANZE / ADMIN</div><h1>${esc(title)}</h1><p class="sub">${esc(sub)}</p></div><div class="toolbar">${buttons}</div></div>`;}
function empty(message){return `<div class="empty">${esc(message)}</div>`;}
function filterBar(resource){return `<form id="filterForm" class="admin-filter"><input type="search" name="query" aria-label="搜索${viewNames[resource]}" placeholder="${resource==='records'?'搜索产品编号（YZ-BC-000001）、名称、材质…':'搜索编号、名称或备注…'}" value="${esc(state.query)}">${resource==='records'?`<select name="kind" aria-label="资料类型"><option value="">全部资料类型</option>${Object.entries(kindNames).map(([k,v])=>`<option value="${k}" ${state.kind===k?'selected':''}>${v}</option>`).join('')}</select>`:''}${['records','samples','plans'].includes(resource)?`<label class="checkbox-line"><input type="checkbox" name="showArchived" ${state.showArchived?'checked':''}>包含已归档</label>`:''}<button class="btn" type="submit">查询</button><button class="btn" type="button" data-action="reset-filters">重置</button></form>`;}
function editableField(label,name,value='',options={}){const {type='text',required=false,full=false,help='',listId='',rows=3,min,max,step}=options;return `<label class="field${full?' full':''}"><span>${esc(label)}${required?' *':''}</span>${type==='textarea'?`<textarea name="${esc(name)}" rows="${rows}" ${required?'required':''}>${esc(txt(value))}</textarea>`:`<input name="${esc(name)}" type="${esc(type)}" value="${esc(txt(value))}" ${required?'required':''} ${listId?`list="${esc(listId)}"`:''} ${min!==undefined?`min="${min}"`:''} ${max!==undefined?`max="${max}"`:''} ${step?`step="${esc(step)}"`:''} ${type==='password'?'autocomplete="new-password" minlength="12"':''}>`}${help?`<small class="help">${esc(help)}</small>`:''}</label>`;}
function selectField(label,name,value,options,help=''){return `<label class="field"><span>${esc(label)}</span><select name="${esc(name)}">${Object.entries(options).map(([k,v])=>`<option value="${esc(k)}" ${String(value??'')===k?'selected':''}>${esc(v)}</option>`).join('')}</select>${help?`<small class="help">${esc(help)}</small>`:''}</label>`;}
function formStatus(){return '<div class="save-status" role="status" data-form-status>修改内容后点击保存。</div>';}
function dialogShell(title,subtitle,body,footer='',className=''){return `<div class="dialog-head"><div><h2 id="dialogTitle">${esc(title)}</h2>${subtitle?`<small>${esc(subtitle)}</small>`:''}</div><button class="close" type="button" data-action="close-dialog" aria-label="关闭">×</button></div>${body}${footer?`<div class="dialog-foot ${esc(className)}">${footer}</div>`:''}`;}
function openDialog(html,nextEditor=null){editor=nextEditor;$('#dialogContent').innerHTML=html;if(!$('#adminDialog').open)$('#adminDialog').showModal();$('#adminDialog').scrollTop=0;}
function canDiscard(){if(editor?.busy||state.busy){toast('正在保存或上传，请稍候。');return false;}return !(editor?.dirty||state.mainDirty)||confirm('有尚未保存的修改，确定放弃这些修改吗？');}
function closeDialog(){if(editor?.busy){toast('正在保存或上传，请稍候。');return;}if(editor?.dirty&&!confirm('有尚未保存的修改，确定关闭并放弃修改吗？'))return;editor=null;$('#adminDialog').close();}
function markDirty(form){if(form?.closest('#adminDialog')&&editor)editor.dirty=true;else if(form?.matches('#settingsForm,#taxonomyForm'))state.mainDirty=true;}
async function loadResource(resource){const response=await api('/api/admin/'+resource);cache[resource]=['settings','taxonomy'].includes(resource)?{value:response.value||{},version:response.version||0}:list(response.items??response);return cache[resource];}
async function navigate(view,force=false){if(!force&&!canDiscard())return;state.mainDirty=false;state.view=view;state.page=1;state.query='';state.showArchived=false;state.kind='';state.auditResource='';closeMobileSidebar();clearTimeout(indexTimer);const seq=++viewSequence;$('#main').innerHTML=empty('正在读取资料…');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumb').textContent='管理后台 / '+viewNames[view];try{if(view==='imports')await loadResource('records');else if(view==='records')await Promise.all([loadResource('records'),loadResource('taxonomy')]);else await loadResource(view);if(seq!==viewSequence)return;render();if(view==='records')loadIndex();}catch(error){if(seq!==viewSequence)return;$('#main').innerHTML=`<div class="panel load-error"><h2>暂时无法读取资料</h2><p class="sub">${esc(errorText(error))}</p><div class="toolbar"><button class="btn primary" data-action="retry">重试</button>${error.status===401?'<a class="btn" href="/login" target="_blank" rel="noopener">重新登录</a>':''}<a class="btn" href="/catalog">返回员工网站</a></div></div>`;}}
function render(){const renderer={records:renderRecords,taxonomy:renderTaxonomy,settings:renderSettings,samples:renderSamples,plans:renderPlans,users:renderUsers,imports:renderImports,audit:renderAudit}[state.view];$('#main').innerHTML=renderer();document.title=viewNames[state.view]+' · 包材库管理后台';}

function renderRecords(){const items=visibleItems('records'),{rows,pages}=pageSlice(items),active=cache.records.filter(r=>!r.archived);return head('产品资料','维护产品参数、历史报价和图片。未知资料可以留空，归档产品不再显示给员工。','<a class="btn" href="/client" target="_blank" rel="noopener">预览客户展示 ↗</a><button class="btn" data-view="imports">批量导入</button><button class="btn primary" data-action="new-record">＋ 新增产品</button>')+`<div class="stats"><div class="stat"><span>在用资料</span><strong>${active.length}</strong></div><div class="stat"><span>在用包材</span><strong>${active.filter(r=>r.kind==='package').length}</strong></div><div class="stat"><span>有图片资料</span><strong>${active.filter(r=>usableImage(r)).length}</strong></div><div class="stat"><span>已归档资料</span><strong>${cache.records.length-active.length}</strong></div></div><div class="panel">${filterBar('records')}<p class="count-note">${items.length} 条符合条件 · 单价、MOQ 与货期可保留原文；工艺标准由业务员参考判断。</p>${rows.length?`<div class="table-wrap"><table><thead><tr><th>图片</th><th>产品资料</th><th>材质／规格</th><th>供应商／报价</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${thumbnail(r)}</td><td class="product-name"><div class="admin-product-code">${esc(r.productCode||(r.kind==='package'?'编号待分配':'原始资料'))}</div><button class="table-name" data-edit-record="${esc(r.id)}">${esc(r.name||'名称待补')}</button><div class="code-line">${esc(r.id)} · ${esc(kindNames[r.kind]||r.kind||'待分类')}</div></td><td>${esc((list(r.materials).join('、')||r.materialRaw||'待补充'))}<div class="code-line">${esc(r.capacityMl!=null?r.capacityMl+' mL':short(r.specificationRaw,50)||'规格待补充')}</div></td><td>${esc(short(r.supplierRaw,35)||'供应商待补充')}<div class="code-line">${esc(short(r.quoteRaw,45)||'报价待补充')}</div></td><td><span class="status-dot${r.archived?' off':''}"></span>${r.archived?'已归档':'在用'}</td><td class="actions"><button class="quiet" data-edit-record="${esc(r.id)}">编辑</button><button class="quiet" data-history="${esc(r.id)}">历史</button><button class="quiet ${r.archived?'':'danger-text'}" data-archive="records" data-id="${esc(r.id)}">${r.archived?'恢复':'归档'}</button></td></tr>`).join('')}</tbody></table></div>${pagination(items.length,pages)}`:empty('没有找到符合条件的资料。')}</div><div id="indexStatus">${indexMarkup()}</div>`;}
function indexMarkup(){const s=state.index;if(!s)return '<div class="admin-index"><div><strong>图片检索</strong><p>正在检查图库索引…</p></div></div>';const busy=!!(s.busy||s.building||s.running||s.rebuilding);return `<div class="admin-index"><div><strong>图片检索${busy?' · 更新中':''}</strong><p>${esc(s.message||s.last_error||(s.available?`目前覆盖 ${s.indexed_images??0} 张图片、${s.indexed_records??0} 条资料。`:'图片索引尚未就绪。'))}</p><p>保存图片或产品后会自动更新索引；未完成或失败时可手动重试。</p></div><button class="btn" data-action="reindex" ${busy?'disabled':''}>${busy?'正在更新…':'更新搜图索引'}</button></div>`;}
async function loadIndex(){try{state.index=await api('/api/admin/search-status');if(state.view==='records'&&$('#indexStatus'))$('#indexStatus').innerHTML=indexMarkup();if(state.view==='records'&&(state.index.busy||state.index.building||state.index.running||state.index.rebuilding)){clearTimeout(indexTimer);indexTimer=setTimeout(loadIndex,5000);}}catch(error){state.index={available:false,message:error.message};if(state.view==='records'&&$('#indexStatus'))$('#indexStatus').innerHTML=indexMarkup();}}
function taxList(key,id){return `<datalist id="${id}">${list(cache.taxonomy.value[key]).map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist>`;}
function openRecord(id){const existing=cache.records.find(r=>r.id===id),r=existing?clone(existing):{id:'',version:0,kind:'package',name:'',images:[],materials:[],uses:[],uncertainties:[]};const moreRaw=[...new Set([...Object.keys(rawLabels),...Object.keys(r).filter(k=>k.endsWith('Raw'))])];const primaryRaw=['materialRaw','specificationRaw','quoteRaw','moqRaw','leadTimeRaw','supplierRaw','contactRaw','remarksRaw'];const body=`<form id="recordForm"><div class="editor-nav" role="tablist" aria-label="产品编辑分组"><button type="button" role="tab" id="tab-basic" aria-controls="panel-basic" aria-selected="true" class="active" data-editor-tab="basic">基础资料</button><button type="button" role="tab" id="tab-quotes" aria-controls="panel-quotes" aria-selected="false" data-editor-tab="quotes">供应商与报价</button><button type="button" role="tab" id="tab-details" aria-controls="panel-details" aria-selected="false" data-editor-tab="details">产品细则</button><button type="button" role="tab" id="tab-images" aria-controls="panel-images" aria-selected="false" data-editor-tab="images">产品图片</button><button type="button" role="tab" id="tab-source" aria-controls="panel-source" aria-selected="false" data-editor-tab="source">其他与来源</button></div><div class="dialog-content">${r.archived?'<div class="admin-warning archive-warning">该产品已归档。编辑保存不会自动恢复展示，请在列表点击“恢复”。</div>':''}<section id="panel-basic" class="editor-panel" role="tabpanel" aria-labelledby="tab-basic" data-editor-panel="basic"><div class="admin-product-code-readonly" role="group" aria-label="只读产品编号"><span>产品编号</span><strong data-product-code>${esc(r.productCode||(r.kind==='package'?'保存后自动分配':'原始资料无需产品编号'))}</strong><small>包材产品由系统自动分配编号，资料修改后保持不变。</small></div><div class="form-grid">${editableField('产品名称','name',r.name,{required:true,full:true})}${selectField('资料类型','kind',r.kind,kindNames)}${editableField('分类','category',r.category,{listId:'categoriesList'})}${editableField('瓶型','bottleType',r.bottleType,{listId:'bottleTypesList'})}${editableField('标准材质','materials',list(r.materials).join('、'),{help:'多个材质用顿号或逗号分隔，例如 PET、PP。'})}${editableField('容量（mL）','capacityMl',r.capacityMl,{type:'number',min:0,step:'any',help:'每个规格独立一条记录；其他规格写在下方规格说明。'})}${editableField('规格说明','specificationRaw',r.specificationRaw)}${editableField('系列名称','series',r.series)}${editableField('款式／型号','model',r.model)}${editableField('用途标签','uses',list(r.uses).join('、'),{full:true,help:'例如 洗发水、沐浴露、乳液；多个用途用顿号分隔。'})}${editableField('材质说明','materialRaw',r.materialRaw,{type:'textarea'})}${editableField('产品说明','description',r.description,{type:'textarea'})}</div>${taxList('categories','categoriesList')}${taxList('bottleTypes','bottleTypesList')}<p class="help editor-section">分类标签可在“分类与检索标签”集中维护。容量、材质未确认时留空，不根据照片推断。</p></section><section id="panel-quotes" class="editor-panel" role="tabpanel" aria-labelledby="tab-quotes" data-editor-panel="quotes" hidden><div class="note admin-note">印刷工艺不设逐款价格必填项。MOQ、货期及最终价格可由业务员结合工艺标准自主判断，历史报价原文继续保留。</div><div class="form-grid">${editableField('供应商名称','supplierRaw',r.supplierRaw)}${editableField('联系方式／联系人','contactRaw',r.contactRaw)}${editableField('采购单价／普通报价','quoteRaw',r.quoteRaw,{type:'textarea',help:'支持原文、阶梯价或待确认说明，不强制拆成数字。'})}${editableField('报价口径','quoteHeader',r.quoteHeader,{type:'textarea',help:'例如含税、不含运；不确定可留空。'})}${editableField('普通起订量 MOQ','moqRaw',r.moqRaw)}${editableField('普通货期','leadTimeRaw',r.leadTimeRaw)}${editableField('确认单价（可选）','unitPrice',r.unitPrice,{type:'number',min:0,step:'any'})}${editableField('币种（可选）','currency',r.currency)}${editableField('报价有效期（可选）','validUntil',r.validUntil,{type:'date'})}${editableField('样品费用','sampleFeeRaw',r.sampleFeeRaw)}</div><details class="editor-section"><summary>定制、开模及其他历史报价</summary><div class="form-grid">${['customQuoteRaw','customMoqRaw','customLeadTimeRaw','moldFeeRaw','processRaw'].map(k=>editableField(rawLabels[k],k,r[k],{type:'textarea'})).join('')}</div></details></section><section id="panel-details" class="editor-panel" role="tabpanel" aria-labelledby="tab-details" data-editor-panel="details" hidden><p class="section-intro">将已确认的参数逐项填写。未知内容可留空，同一项目可重复填写以保留阶梯报价；资料来源与原文依据用于后续核对。</p><div id="productDetailsEditor"></div><div class="toolbar editor-section"><button type="button" class="btn" data-detail-op="add">＋ 添加细则</button><span class="help">最多 60 项；保存后与其他产品资料一同保留历史版本。</span></div></section><section id="panel-images" class="editor-panel" role="tabpanel" aria-labelledby="tab-images" data-editor-panel="images" hidden><div class="note">列表优先展示已核对单品图；同款系列参考会明确标注。整页及待核对图片保留作来源证据，不能设为产品首图；修改图片用途不会改变审核状态。</div><div class="toolbar editor-section"><label class="btn"><input id="productImageFiles" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden>＋ 上传单款图片</label><span class="help">每张仅一个包材，组图请先拆分后上传。JPEG、PNG、WebP；单张不超过 10 MB</span></div><p class="image-error" role="alert" id="imageUploadError"></p><div id="imageEditorGrid" class="image-editor-grid"></div></section><section id="panel-source" class="editor-panel" role="tabpanel" aria-labelledby="tab-source" data-editor-panel="source" hidden><div class="form-grid">${editableField('其他备注','remarksRaw',r.remarksRaw,{type:'textarea',full:true})}${editableField('来源补充说明','sourceNote',r.sourceNote,{type:'textarea',full:true,help:'可填写供应商新资料、修订依据或图册页码。'})}${editableField('待确认事项','uncertainties',list(r.uncertainties).join('\n'),{type:'textarea',full:true,help:'每行一项；确认解决后可删除对应项。'})}${moreRaw.filter(k=>!primaryRaw.includes(k)&&!['sampleFeeRaw','customQuoteRaw','customMoqRaw','customLeadTimeRaw','moldFeeRaw','processRaw'].includes(k)).map(k=>editableField(rawLabels[k]||k,k,r[k],{type:'textarea'})).join('')}</div><details class="editor-section"><summary>查看原始资料与来源（只读）</summary><p class="help">原始单元格和来源保持可追溯。上方修订内容会保存为新版本。</p><pre class="source-box mono">${esc(JSON.stringify({id:r.id||'保存后自动生成编号',source:r.source||null,rawCells:r.rawCells||null,provenance:r.provenance||null,formulaCachedValues:r.formulaCachedValues||null},null,2))}</pre></details></section></div><div class="dialog-foot">${formStatus()}<button type="button" class="btn" data-action="close-dialog">取消</button><button type="submit" class="btn primary">保存产品</button></div></form>`;openDialog(dialogShell(existing?'编辑产品':'新增产品',existing?`${r.productCode||'编号待分配'} · 版本 ${r.version??0}`:'先填写名称，其余缺失信息可以后续补充。',body),{type:'record',record:r,dirty:false,busy:false,images:clone(list(r.images)),productDetails:clone(list(r.productDetails))});renderImages();renderProductDetails();}
const detailSourceFields=['name','kind','category','bottleType','series','model','description','quoteHeader','sourceNote',...Object.keys(rawLabels)];
function renderProductDetails(){
  const container=$('#productDetailsEditor');
  if(editor?.type!=='record'||!container)return;
  container.innerHTML=editor.productDetails.length?`<div class="table-wrap"><table><thead><tr><th>项目</th><th>具体内容</th><th>资料来源与依据</th><th>操作</th></tr></thead><tbody>${editor.productDetails.map((item,index)=>`<tr data-detail-row="${index}"><td><label class="field"><span>项目 ${index+1}</span><input data-detail-field="label" data-detail-index="${index}" aria-label="细则 ${index+1} 项目" maxlength="80" value="${esc(item.label||'')}" placeholder="例如：口径、普通起订量" required></label></td><td><label class="field"><span>具体内容</span><textarea data-detail-field="value" data-detail-index="${index}" aria-label="细则 ${index+1} 内容" rows="3" maxlength="2000" placeholder="未知时留空">${esc(item.value||'')}</textarea></label></td><td><label class="field"><span>资料来源</span><select data-detail-field="sourceField" data-detail-index="${index}" aria-label="细则 ${index+1} 资料来源"><option value="">未指定／其他资料</option>${detailSourceFields.map(key=>`<option value="${key}" ${item.sourceField===key?'selected':''}>${esc(fieldNames[key]||key)}</option>`).join('')}</select></label><label class="field"><span>原文依据</span><textarea data-detail-field="evidence" data-detail-index="${index}" aria-label="细则 ${index+1} 原文依据" rows="3" maxlength="2000" placeholder="摘录资料原文，或填写补充依据">${esc(item.evidence||'')}</textarea></label></td><td><button type="button" class="quiet danger-text" data-detail-op="remove" data-detail-index="${index}" aria-label="删除细则 ${index+1}">删除</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="help">暂无产品细则。可添加已确认的参数，其余以后补充。</p>';
  const add=$('[data-detail-op="add"]');
  if(add)add.disabled=editor.busy||editor.productDetails.length>=60;
}
function readProductDetails(form){
  return [...form.querySelectorAll('[data-detail-row]')].map(row=>Object.fromEntries(
    [...row.querySelectorAll('[data-detail-field]')].map(input=>[input.dataset.detailField,input.value.trim()])));
}
function updateProductDetail(input){
  if(editor?.type!=='record'||editor.busy||!input.dataset.detailField)return;
  const row=editor.productDetails[Number(input.dataset.detailIndex)];
  if(row&&['label','value','sourceField','evidence'].includes(input.dataset.detailField)){
    row[input.dataset.detailField]=input.value;editor.dirty=true;
  }
}
function changeProductDetail(button){
  if(editor?.type!=='record'||editor.busy)return;
  editor.productDetails=readProductDetails($('#recordForm'));
  let focusIndex;
  if(button.dataset.detailOp==='add'){
    if(editor.productDetails.length>=60){toast('产品细则最多 60 项。');return;}
    editor.productDetails.push({label:'',value:'',sourceField:'',evidence:''});
    focusIndex=editor.productDetails.length-1;
  }else if(button.dataset.detailOp==='remove'){
    const index=Number(button.dataset.detailIndex);
    if(!Number.isInteger(index)||index<0||index>=editor.productDetails.length)return;
    editor.productDetails.splice(index,1);focusIndex=Math.min(index,editor.productDetails.length-1);
  }else return;
  editor.dirty=true;renderProductDetails();
  (focusIndex>=0?$(`[data-detail-field="label"][data-detail-index="${focusIndex}"]`):$('[data-detail-op="add"]'))?.focus();
}
function canSetPrimary(image,index){return index>0&&isProductImage(image)&&!(imageScope(image)==='same_style_variants'&&editor.images.some(i=>isProductImage(i)&&imageScope(i)==='single_product'));}
function renderImages(){if(editor?.type!=='record'||!$('#imageEditorGrid'))return;const first=editor.images.indexOf(primaryImage({...editor.record,images:editor.images}));$('#imageEditorGrid').innerHTML=editor.images.length?editor.images.map((i,n)=>`<div class="image-editor-card"><div class="image-editor-photo">${i.missing?'<span class="help">原图文件缺失</span>':`<img src="${esc(imageURL(i))}" alt="产品图 ${n+1}" loading="lazy">`}${n===first?'<span class="tag">优先展示</span>':''}</div><div class="image-editor-fields"><p class="help image-scope-note">${esc(imageScopeLabel(i,editor.record))}</p><input aria-label="图片 ${n+1} 的说明" data-image-field="caption" data-index="${n}" value="${esc(i.caption||'')}" placeholder="图片说明（可选）"><select aria-label="图片 ${n+1} 的用途" data-image-field="role" data-index="${n}">${Object.entries({product:'产品图片',supplier:'供应商图片',inquiry:'询价图片',reference:'参考图片','floating-reference':'浮动参考图',other:'其他原图','test-plan':'测试计划图片'}).map(([k,v])=>`<option value="${k}" ${(i.role===k||k==='reference'&&!['product','supplier','inquiry','reference','floating-reference','other','test-plan'].includes(i.role))?'selected':''}>${v}</option>`).join('')}</select>${i.uncertain?'<p class="help">原资料对应关系待确认，不参与搜图。</p>':'<p class="help">选为参考图片可排除在相似检索外。</p>'}<label class="checkbox-line"><input type="checkbox" data-image-field="clientVisible" data-index="${n}" ${i.clientVisible===true?'checked':''}>允许客户展示（确认图片不含供应商、报价或联系方式）</label><div class="image-editor-buttons"><button type="button" class="quiet" data-image-op="first" data-index="${n}" ${!canSetPrimary(i,n)?'disabled':''} title="单品图优先于系列参考；原页及待核对图不能设为首图">${imageScope(i)==='same_style_variants'?'设为系列首图':'设为首图'}</button><button type="button" class="quiet" aria-label="前移图片 ${n+1}" data-image-op="up" data-index="${n}" ${n===0?'disabled':''}>↑</button><button type="button" class="quiet" aria-label="后移图片 ${n+1}" data-image-op="down" data-index="${n}" ${n===editor.images.length-1?'disabled':''}>↓</button><button type="button" class="quiet danger-text" data-image-op="remove" data-index="${n}">移除</button></div><div class="image-file-path">${esc(i.path||i.file||'')}</div></div></div>`).join(''):empty('尚未添加图片，点击上方按钮上传。');if(editor.busy)setDialogButtons(true);}
function recordFromForm(form){const d=Object.fromEntries(new FormData(form)),record=clone(editor.record);for(const [key,value] of Object.entries(d)){if(['materials','uses'].includes(key))record[key]=splitTags(value);else if(key==='uncertainties')record[key]=String(value).split('\n').map(v=>v.trim()).filter(Boolean);else if(['capacityMl','unitPrice'].includes(key))record[key]=value===''?null:Number(value);else record[key]=value;}record.images=clone(editor.images);record.productDetails=readProductDetails(form);delete record.productCode;return record;}
async function saveRecord(form){if(editor?.busy)return;const record=recordFromForm(form);if(!record.name.trim()){activateEditorTab('basic');form.elements.name.reportValidity();return;}await withEditorSave(form,async()=>{await api('/api/admin/records',{action:'save',id:record.id||undefined,version:record.version||0,record});await loadResource('records');});}
function activateEditorTab(tab){document.querySelectorAll('[data-editor-tab]').forEach(b=>{const selected=b.dataset.editorTab===tab;b.classList.toggle('active',selected);b.setAttribute('aria-selected',String(selected));});document.querySelectorAll('[data-editor-panel]').forEach(p=>p.hidden=p.dataset.editorPanel!==tab);}
async function uploadImages(files){if(editor?.type!=='record'||editor.busy)return;const target=editor;target.busy=true;$('#imageUploadError').textContent='正在处理并上传图片…';setDialogButtons(true);try{for(const file of files){if(editor!==target)break;if(file.size>10*1024*1024)throw Error(`${file.name} 超过 10 MB，请压缩后上传。`);if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error(`${file.name} 格式不支持，请选择 JPEG、PNG 或 WebP。`);const bitmap=await createImageBitmap(file);try{if(bitmap.width<16||bitmap.height<16||bitmap.width*bitmap.height>20000000||Math.max(bitmap.width,bitmap.height)>10000)throw Error('图片尺寸不合适，请选择边长至少 16 像素、总像素不超过 2000 万的图片。');const factor=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*factor);canvas.height=Math.round(bitmap.height*factor);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const result=await api('/api/admin/uploads',{image:canvas.toDataURL('image/jpeg',.9)});if(!result.image?.path)throw Error('上传结果缺少图片路径，请重试。');target.images.push({...result.image,role:'product',caption:file.name.replace(/\.[^.]+$/,'')});target.dirty=true;renderImages();}finally{bitmap.close();}}$('#imageUploadError').textContent='图片已上传，请保存产品使图片关联生效。';}catch(error){$('#imageUploadError').textContent=errorText(error);}finally{target.busy=false;setDialogButtons(false);const input=$('#productImageFiles');if(input)input.value='';}}
function setDialogButtons(disabled){$('#adminDialog').querySelectorAll('button,input,select,textarea').forEach(control=>{if(disabled){if(control.dataset.priorDisabled===undefined)control.dataset.priorDisabled=String(control.disabled);control.disabled=true;}else if(control.dataset.priorDisabled!==undefined){control.disabled=control.dataset.priorDisabled==='true';delete control.dataset.priorDisabled;}});}
async function withEditorSave(form,work){const current=editor;current.busy=true;setDialogButtons(true);const status=form.querySelector('[data-form-status]');status.textContent='正在保存…';status.classList.remove('error');try{const result=await work();current.dirty=false;editor=null;$('#adminDialog').close();if(result?.reauth){state.mainDirty=false;location.href='/login';return;}render();if(state.view==='records')loadIndex();toast('已保存，员工刷新页面后可查看最新资料。');}catch(error){setFormError(form,error);}finally{current.busy=false;setDialogButtons(false);}}

function renderSettings(){const settings=cache.settings.value;const fields=[['siteTitle','浏览器页面标题'],['brandName','侧栏品牌名称'],['englishName','品牌英文名称'],['companyName','公司名称'],['catalogTitle','产品展示页标题'],['catalogSubtitle','产品展示页说明'],['footerNote','页脚说明'],['announcement','站内公告'],['processReference','印刷工艺参考标准']];return head('网站内容','修改员工网站的名称、说明与公告；工艺参考标准由业务员结合实际要求判断。')+`<form id="settingsForm" class="panel"><div class="setting-grid">${fields.map(([key,label])=>`<div class="${['catalogSubtitle','footerNote','announcement','processReference'].includes(key)?'wide':''}">${editableField(label,key,settings[key],{type:['catalogSubtitle','footerNote','announcement','processReference'].includes(key)?'textarea':'text',required:['siteTitle','companyName','catalogTitle'].includes(key),help:key==='processReference'?'可先留空。仅展示参考标准，不自动计算 MOQ、货期或报价。':''})}</div>`).join('')}<label class="checkbox-line wide"><input type="checkbox" name="showBusinessDemo" ${settings.showBusinessDemo?'checked':''}>在员工网站显示“业务系统演示”入口（演示数据，不用于正式业务）</label></div><div class="save-bar">${formStatus()}<button class="btn primary" type="submit">保存网站内容</button></div></form>`;}
function renderTaxonomy(){const tax=cache.taxonomy.value;const groups=[['categories','包材分类','例如：瓶类、罐与广口盒、软管、泵头与喷头、外包装'],['materials','材质','例如：玻璃、PET、PETG、PE、PP、铝、纸'],['bottleTypes','瓶型与结构','例如：圆瓶、方瓶、扁瓶、真空瓶、泡沫瓶、广口瓶'],['uses','用途／料体类型','例如：乳液、面霜、精华、洗发水、沐浴露']];return head('分类与检索标签','按分类、材质、瓶型和用途分别维护，避免把多种维度混在同一层分类。')+`<div class="note admin-note">每行一个标签。修改标签词表不会批量改写既有产品，已有资料仍会保留；产品编辑时可补充对应标签。</div><form id="taxonomyForm" class="panel"><div class="setting-grid">${groups.map(([key,label,help])=>`<label class="field tag-editor"><span>${label}</span><textarea name="${key}" rows="9">${esc(list(tax[key]).join('\n'))}</textarea><small class="help">${help}</small></label>`).join('')}</div><div class="save-bar">${formStatus()}<button class="btn primary" type="submit">保存分类词表</button></div></form>`;}
async function saveSingleton(form,resource){if(state.busy)return;state.busy=true;const button=form.querySelector('button[type=submit]');button.disabled=true;const value={...cache[resource].value},d=Object.fromEntries(new FormData(form));for(const [key,v] of Object.entries(d))value[key]=resource==='taxonomy'?splitTags(v):v;if(resource==='settings')value.showBusinessDemo=form.elements.showBusinessDemo.checked;try{await api('/api/admin/'+resource,{action:'save',version:cache[resource].version,value});await loadResource(resource);state.mainDirty=false;render();toast('已保存。');}catch(error){setFormError(form,error);}finally{state.busy=false;button.disabled=false;}}

function renderSamples(){const items=visibleItems('samples'),{rows,pages}=pageSlice(items);return head('实物样品','维护样品编号、对应产品、存放位置和借还信息。流转记录保留可追溯。','<button class="btn primary" data-action="new-sample">＋ 新增样品</button>')+`<div class="panel">${filterBar('samples')}<p class="count-note">${items.length} 件实物样品</p>${rows.length?`<div class="table-wrap"><table><thead><tr><th>样品编号／关联产品</th><th>位置与状况</th><th>状态／借用人</th><th>预计归还</th><th>操作</th></tr></thead><tbody>${rows.map(s=>`<tr><td><button class="table-name" data-edit-sample="${esc(s.id)}">${esc(s.id)}</button><div class="code-line">${esc(s.record_id||'产品待关联')}</div></td><td>${esc(s.location||'位置待补充')}<div class="code-line">${esc(s.condition||'')}</div></td><td>${s.archived?'<span class="tag">已归档</span>':esc(statusNames[s.status]||s.status||'待确认')}<div class="code-line">${esc(s.borrower||'')}</div></td><td>${esc(s.due||'—')}</td><td class="actions"><button class="quiet" data-edit-sample="${esc(s.id)}">编辑</button><button class="quiet" data-sample-events="${esc(s.id)}">流转记录</button><button class="quiet ${s.archived?'':'danger-text'}" data-archive="samples" data-id="${esc(s.id)}">${s.archived?'恢复':'归档'}</button></td></tr>`).join('')}</tbody></table></div>${pagination(items.length,pages)}`:empty('尚无实物样品档案。')}</div>`;}
async function openSample(id){if(!cache.records.length)await loadResource('records');const existing=cache.samples.find(i=>i.id===id),s=existing?clone(existing):{id:'',record_id:'',version:0,status:'available',condition:'完好'};const body=`<form id="sampleForm"><div class="dialog-content"><div class="form-grid">${editableField('样品编号','id',s.id,{required:true,help:existing?'既有样品编号保持不变。':'每件独立借还的实物使用一个编号。'})}${editableField('对应产品编号','record_id',s.record_id,{required:true,listId:'recordOptions'})}${editableField('存放位置','location',s.location,{required:true,help:'例如：样品室 A 柜／2 层／03 格'})}${editableField('样品状况','condition',s.condition,{required:true})}${selectField('样品状态','status',s.status,statusNames,'借出时填写借用人和归还日期；其他状态会清空这两项。')}${editableField('借用人','borrower',s.borrower)}${editableField('预计归还日期','due',s.due,{type:'date'})}</div><datalist id="recordOptions">${cache.records.filter(r=>!r.archived||r.id===s.record_id).map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('')}</datalist><p class="help editor-section">这里用于登记和修正实物档案；保存操作会进入管理修改记录。</p></div><div class="dialog-foot">${formStatus()}<button type="button" class="btn" data-action="close-dialog">取消</button><button type="submit" class="btn primary">保存样品</button></div></form>`;openDialog(dialogShell(existing?'编辑实物样品':'新增实物样品',existing?`版本 ${s.version??0}`:'仅登记实际收到的实物。',body),{type:'sample',record:s,dirty:false,busy:false});if(existing)$('#sampleForm').elements.id.readOnly=true;setSampleBorrowFields();}
function setSampleBorrowFields(){const f=$('#sampleForm');if(!f)return;const lent=f.elements.status.value==='lent';for(const key of ['borrower','due']){f.elements[key].disabled=!lent;f.elements[key].required=lent;}}
function renderPlans(){const items=visibleItems('plans'),{rows,pages}=pageSlice(items);return head('选型方案','维护方案名称、备注和归档状态。方案内的产品快照保留保存当时内容。')+`<div class="panel">${filterBar('plans')}<p class="count-note">${items.length} 个选型方案</p>${rows.length?`<div class="table-wrap"><table><thead><tr><th>方案</th><th>产品数量</th><th>备注</th><th>创建时间</th><th>操作</th></tr></thead><tbody>${rows.map(p=>`<tr><td><button class="table-name" data-edit-plan="${esc(p.id)}">${esc(p.title||'未命名方案')}</button><div class="code-line">${esc(p.id)} ${p.archived?' · 已归档':''}</div></td><td>${list(p.snapshot).length}</td><td>${esc(short(p.note,100)||'—')}</td><td>${esc(dateLabel(p.created))}</td><td class="actions"><button class="quiet" data-edit-plan="${esc(p.id)}">编辑／查看</button><button class="quiet ${p.archived?'':'danger-text'}" data-archive="plans" data-id="${esc(p.id)}">${p.archived?'恢复':'归档'}</button></td></tr>`).join('')}</tbody></table></div>${pagination(items.length,pages)}`:empty('尚无选型方案。')}</div>`;}
function openPlan(id){const p=cache.plans.find(i=>i.id===id);if(!p)return;const body=`<form id="planForm"><div class="dialog-content"><div class="form-grid">${editableField('方案名称','title',p.title,{required:true,full:true})}${editableField('方案备注','note',p.note,{type:'textarea',full:true})}</div><div class="editor-section"><h3>产品快照 · ${list(p.snapshot).length} 条</h3><p class="section-intro">以下为保存方案时的产品内容，避免后续修改影响历史选型依据。</p><div class="snapshot-list">${list(p.snapshot).map(r=>`<div class="snapshot-item"><strong>${esc(r.name||r.id||'产品')}</strong><p>${esc(r.id||'')} · ${esc(r.specificationRaw||'规格待补')}</p><p>${esc(r.quoteRaw||'报价待补')}</p><details><summary>查看完整快照</summary><pre class="mono">${esc(JSON.stringify(r,null,2))}</pre></details></div>`).join('')||'<p class="help">此方案没有产品快照。</p>'}</div></div></div><div class="dialog-foot">${formStatus()}<button type="button" class="btn" data-action="close-dialog">关闭</button><button type="submit" class="btn primary">保存方案</button></div></form>`;openDialog(dialogShell('编辑选型方案',`${p.id} · 版本 ${p.version??0}`,body),{type:'plan',record:clone(p),dirty:false,busy:false});}

function renderUsers(){const items=visibleItems('users'),{rows,pages}=pageSlice(items);return head('员工与权限','管理员维护网站资料和账号；员工查询与选型；客户账号仅查看获准展示的包材图片和净含量。','<button class="btn primary" data-action="new-user">＋ 创建账号</button>')+`<div class="note admin-note">建议每位员工使用独立账号。密码至少 12 个字符；停用账号后将不能继续登录。账号密码不会显示或导出。</div><div class="panel">${filterBar('users')}<p class="count-note">${items.length} 个账号</p>${rows.length?`<div class="table-wrap"><table><thead><tr><th>账号／姓名</th><th>权限</th><th>状态</th><th>更新时间</th><th>操作</th></tr></thead><tbody>${rows.map(u=>`<tr><td><button class="table-name" data-edit-user="${esc(u.id||u.username)}">${esc(u.name||u.id||u.username)}</button><div class="code-line">${esc(u.id||u.username)}${(u.id||u.username)===session.username?' · 当前账号':''}</div></td><td><span class="tag ${u.role==='admin'?'blue':''}">${esc(userRoleNames[u.role]||'未知权限')}</span></td><td><span class="status-dot${u.active===false?' off':''}"></span>${u.active===false?'已停用':'启用'}</td><td>${esc(dateLabel(u.updated||u.created))}</td><td><button class="quiet" data-edit-user="${esc(u.id||u.username)}">编辑／重置密码</button></td></tr>`).join('')}</tbody></table></div>${pagination(items.length,pages)}`:empty('没有找到账号。')}</div>`;}
function openUser(id){const existing=cache.users.find(u=>(u.id||u.username)===id),u=existing?clone(existing):{id:'',name:'',version:0,role:'employee',active:true};const body=`<form id="userForm"><div class="dialog-content"><div class="form-grid">${editableField('登录账号','id',u.id||u.username,{required:true,help:existing?'既有登录账号保持不变。':'建议使用英文、数字、短横线或下划线。'})}${editableField('姓名／显示名称','name',u.name,{required:true})}${selectField('账号权限','role',u.role,{employee:'员工 · 查询与选型',client:'客户 · 仅图片与净含量',admin:'管理员 · 维护全部业务资料'})}${selectField('账号状态','active',u.active===false?'false':'true',{true:'启用',false:'停用'})}${editableField(existing?'重置密码（留空不修改）':'初始密码','password','',{type:'password',required:!existing,full:true,help:'至少 12 个字符。请通过公司内部渠道交给对应员工。'})}</div><p class="help editor-section">系统会保留至少一个可用管理员，防止管理权限丢失。</p></div><div class="dialog-foot">${formStatus()}<button type="button" class="btn" data-action="close-dialog">取消</button><button type="submit" class="btn primary">${existing?'保存账号':'创建账号'}</button></div></form>`;openDialog(dialogShell(existing?'编辑账号':'创建账号',existing?`${u.id||u.username} · 版本 ${u.version??0}`:'独立账号便于区分操作人和管理权限。',body),{type:'user',record:u,dirty:false,busy:false});if(existing)$('#userForm').elements.id.readOnly=true;}
async function saveSimple(form,resource){if(editor?.busy)return;const fields=Object.fromEntries(new FormData(form)),original=editor.record;const payload={action:'save',...fields,id:original.id||original.username||fields.id,version:original.version||0};if(resource==='samples'&&fields.status!=='lent'){payload.borrower='';payload.due='';}if(resource==='users'){payload.active=fields.active==='true';if(!fields.password)delete payload.password;if(fields.role==='admin'&&original.role!=='admin'&&!confirm('该账号将可维护全部网站资料和员工账号，确定授予管理员权限吗？'))return;if(payload.active===false&&original.active!==false&&!confirm('确定停用该账号吗？该员工将不能继续登录。'))return;}await withEditorSave(form,async()=>{await api('/api/admin/'+resource,payload);if(resource==='users'&&payload.id===session.username&&(payload.password||payload.role!==original.role||payload.active!==original.active))return {reauth:true};await loadResource(resource);});}
async function archiveItem(resource,id){const item=cache[resource].find(r=>(r.id||r.username)===id);if(!item)return;const restore=!!item.archived;if(!confirm(restore?`确定恢复“${item.name||item.title||item.id}”吗？恢复后员工可再次看到。`:`确定归档“${item.name||item.title||item.id}”吗？归档后从员工视图隐藏，仍可在后台恢复。`))return;await api('/api/admin/'+resource,{action:restore?'unarchive':'archive',id,version:item.version||0});await loadResource(resource);render();if(resource==='records')loadIndex();toast(restore?'已恢复。':'已归档，历史记录保留。');}

function parseSnapshot(value){if(typeof value==='string'){try{return JSON.parse(value);}catch{return value;}}return value;}
function changes(item){const before=parseSnapshot(item.before)||{},after=parseSnapshot(item.after)||{};if(typeof before!=='object'||typeof after!=='object')return '';return [...new Set([...Object.keys(before),...Object.keys(after)])].filter(k=>!['updated','version','searchText'].includes(k)&&JSON.stringify(before[k])!==JSON.stringify(after[k])).map(k=>fieldNames[k]||k).slice(0,12).join('、');}
function renderAudit(){let items=list(cache.audit);if(state.auditResource)items=items.filter(i=>i.resource===state.auditResource);if(state.query.trim()){const q=state.query.toLowerCase();items=items.filter(i=>[i.entity_id,i.resource,i.action,i.actor,changes(i)].join(' ').toLowerCase().includes(q));}const {rows,pages}=pageSlice(items);return head('修改记录','查看操作人、时间与变更内容。产品可以恢复至已有历史版本，恢复本身也会留痕。')+`<div class="panel"><form id="auditFilter" class="audit-filters"><input type="search" name="query" placeholder="搜索资料编号、账号或修改字段…" aria-label="搜索修改记录" value="${esc(state.query)}"><select name="resource" aria-label="资料类型"><option value="">全部类型</option>${Object.entries(resourceNames).map(([k,v])=>`<option value="${k}" ${state.auditResource===k?'selected':''}>${v}</option>`).join('')}</select><button class="btn">查询</button></form><p class="count-note">当前读取 ${cache.audit.length} 条修改记录，筛选结果 ${items.length} 条。</p>${rows.length?`<div class="table-wrap"><table><thead><tr><th>时间／操作人</th><th>资料</th><th>操作</th><th>变更字段</th><th>详情</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${esc(dateLabel(a.created))}<div class="code-line">${esc(a.actor||'—')}</div></td><td>${esc(resourceNames[a.resource]||a.resource)}<div class="code-line">${esc(a.entity_id||'—')}</div></td><td class="audit-action">${esc(actionNames[a.action]||a.action)}</td><td class="audit-summary">${esc(changes(a)||'—')}</td><td><button class="quiet" data-audit="${esc(a.id)}">查看</button></td></tr>`).join('')}</tbody></table></div>${pagination(items.length,pages)}`:empty('尚无符合条件的修改记录。')}</div>`;}
function openAudit(id){const a=cache.audit.find(i=>String(i.id)===String(id));if(!a)return;openDialog(dialogShell('修改详情',`${dateLabel(a.created)} · ${a.actor||''} · ${actionNames[a.action]||a.action}`,`<div class="dialog-content"><p class="sub">${esc(resourceNames[a.resource]||a.resource)} · ${esc(a.entity_id)}</p><div class="audit-diff editor-section"><section><h3>修改前</h3><pre>${esc(JSON.stringify(parseSnapshot(a.before),null,2)||'无')}</pre></section><section><h3>修改后</h3><pre>${esc(JSON.stringify(parseSnapshot(a.after),null,2)||'无')}</pre></section></div></div>`,'<button class="btn" data-action="close-dialog">关闭</button>'));}
async function openHistory(id){const response=await api('/api/admin/audit?resource=records&id='+encodeURIComponent(id));const record=cache.records.find(r=>r.id===id);if(!record)return;const revisions=list(response.items??response).filter(a=>a.resource==='records'&&a.entity_id===id);openDialog(dialogShell('产品历史版本',`${record.name||record.id} · 当前版本 ${record.version??0}`,`<div class="dialog-content"><div class="note admin-note">恢复会创建一个新版本，保留全部历史。恢复前请查看当时内容；图片如有调整，恢复后会自动更新搜图索引。</div><div class="revision-list">${revisions.map(a=>`<div class="revision"><div class="revision-top"><div><strong>${esc(actionNames[a.action]||a.action)} · ${esc(dateLabel(a.created))}</strong><p>${esc(a.actor||'')} · ${esc(changes(a)||'资料保存')}</p></div>${a.after?`<button class="btn small" data-restore-revision="${esc(a.id)}" data-record-id="${esc(id)}">恢复此版本</button>`:''}</div><details><summary>查看此版本内容</summary><pre class="mono">${esc(JSON.stringify(parseSnapshot(a.after),null,2))}</pre></details></div>`).join('')||empty('暂时没有管理修改记录。首次保存后会生成历史版本。')}</div></div>`,'<button class="btn" data-action="close-dialog">关闭</button>'),{type:'history',record:clone(record),dirty:false,busy:false});}
async function restoreRevision(id,revision){if(!confirm('确定恢复为所选历史版本吗？当前内容将保留在历史中，恢复后的产品会作为新版本保存。'))return;const r=cache.records.find(v=>v.id===id);if(!r)return;const e=editor;e.busy=true;setDialogButtons(true);try{await api('/api/admin/records',{action:'restore',id,version:r.version||0,revision:Number(revision)});await loadResource('records');editor=null;$('#adminDialog').close();render();loadIndex();toast('已恢复所选版本。');}finally{e.busy=false;setDialogButtons(false);}}
async function sampleEvents(id){const events=await api('/api/samples/'+encodeURIComponent(id)+'/history');const items=list(events.items??events);openDialog(dialogShell('样品流转记录',id,`<div class="dialog-content revision-list">${items.map(e=>`<div class="revision"><strong>${esc(({register:'登记',lend:'借出',return:'归还',consumed:'测试耗用',sent:'寄给客户'})[e.action]||actionNames[e.action]||e.action)}</strong><p>${esc(dateLabel(e.created))} · ${esc(e.actor)}</p><pre class="mono">${esc(JSON.stringify(parseSnapshot(e.details),null,2))}</pre></div>`).join('')||empty('暂无流转记录；管理员修订记录可在“修改记录”中查看。')}</div>`,'<button class="btn" data-action="close-dialog">关闭</button>'));}

function renderImports(){const p=state.importPreview,errors=list(p?.errors),canCommit=!!(p?.token&&p.valid!==false&&!errors.length&&!state.importBusy);return head('批量导入与导出','先预览字段与错误，再一次性确认写入。原始图册中的缺失信息可保留为空。')+`<div class="panel"><div class="panel-title"><h2>导入产品资料</h2><a class="btn small" href="/api/admin/import/template" download>下载 CSV 模板</a></div><p class="section-intro">使用模板字段填写 CSV，或上传按同样表头整理的 Excel（.xlsx）。更新已有产品需保留 id（原始记录编号）和版本；productCode 为只读产品编号。不直接解析 PDF 图册或从照片推断参数。</p><div class="file-choice"><label class="field"><span>选择 CSV / XLSX 文件</span><input type="file" id="importFile" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" ${state.importBusy?'disabled':''}><small class="help">文件不超过 10 MB；预览完成前不会写入产品资料。</small></label></div><p id="importStatus" class="save-status" role="status">${state.importBusy?'正在处理文件…':esc(state.importName||'选择文件后生成预览。')}</p>${p?`<div class="import-preview"><div class="note">识别 ${Number(p.count??p.rows?.length??0)} 条记录。${errors.length?`${errors.length} 处问题需修正。`:'请核对以下预览，确认后再导入。'}</div>${list(p.warnings).length?`<div class="admin-warning editor-section">${p.warnings.map(w=>`<div>${esc(w)}</div>`).join('')}</div>`:''}${errors.length?`<ul class="import-error-list danger-text">${errors.map(e=>`<li>${e.row!=null?'第 '+esc(e.row)+' 行：':''}${esc(e.message||e.error||txt(e))}</li>`).join('')}</ul>`:''}${list(p.rows).length?`<div class="table-wrap editor-section"><table><thead><tr><th>编号</th><th>名称</th><th>材质／规格</th><th>供应商</th><th>报价／MOQ</th></tr></thead><tbody>${p.rows.slice(0,50).map(row=>{const r=row.record||row;return `<tr><td>${esc(r.id||'新建')}</td><td>${esc(r.name||'—')}</td><td>${esc((list(r.materials).join('、')||r.materialRaw||'')+' '+(r.specificationRaw||''))}</td><td>${esc(r.supplierRaw||'—')}</td><td>${esc(r.quoteRaw||'—')}<div class="code-line">${esc(r.moqRaw||'')}</div></td></tr>`;}).join('')}</tbody></table></div><p class="help">预览最多显示前 50 行；确认时按整份已校验的文件导入。</p>`:''}<div class="save-bar"><button class="btn" data-action="clear-import" ${state.importBusy?'disabled':''}>清除预览</button><button class="btn primary" data-action="commit-import" ${canCommit?'':'disabled'}>确认导入 ${Number(p.count??p.rows?.length??0)} 条记录</button></div></div>`:''}</div><div class="panel"><h2>导出资料</h2><p class="section-intro">导出当前产品完整资料（包含归档产品）。CSV 包含可回导的常用字段和版本号，不含产品细则；使用 CSV 更新已有产品时会保留细则。完整备份请使用 JSON，保留产品细则、图片关联、来源与全部产品字段。全部管理资料导出还包括网站设置、分类、样品、方案和历史记录，不包含员工密码。</p><div class="import-actions"><button class="btn" data-action="export-csv">导出产品 CSV</button><button class="btn" data-action="export-json">导出完整产品 JSON</button><a class="btn" href="/api/admin/export" download>导出全部管理资料 JSON</a></div></div>`;}
function readFileBase64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(Error('文件读取失败，请重新选择。'));r.readAsDataURL(file);});}
async function previewImport(file){if(!file||state.importBusy)return;if(file.size>10*1024*1024)throw Error('导入文件超过 10 MB，请拆分后再导入。');if(!/\.(csv|xlsx)$/i.test(file.name))throw Error('请选择 CSV 或 XLSX 文件。');state.importBusy=true;state.importPreview=null;state.importName=file.name;render();try{const content=await readFileBase64(file);state.importPreview=await api('/api/admin/import/preview',{filename:file.name,content});}catch(error){state.importPreview={errors:[{message:errorText(error)}],rows:[],valid:false};}finally{state.importBusy=false;if(state.view==='imports')render();}}
async function commitImport(){const preview=state.importPreview;if(!preview?.token||state.importBusy)return;if(!confirm(`确认写入本次预览的 ${preview.count??preview.rows?.length??0} 条产品资料吗？更新将产生版本与修改记录。`))return;state.importBusy=true;render();try{const result=await api('/api/admin/import/commit',{token:preview.token});state.importPreview=null;state.importName='';await loadResource('records');toast(`导入完成${result.count!=null?'：'+result.count+' 条资料':''}。`);}catch(error){preview.errors=[{message:errorText(error)+' 请重新选择文件并生成新预览。'}];preview.valid=false;preview.token=null;}finally{state.importBusy=false;if(state.view==='imports')render();}}
function download(content,name,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportProducts(format){const records=cache.records;if(format==='json'){download(JSON.stringify({exportedAt:new Date().toISOString(),records},null,2),'源泽包材-完整产品资料.json','application/json');return;}const columns=['productCode','id','version','name','kind','category','bottleType','materials','capacityMl','specificationRaw','series','model','uses','supplierRaw','moqRaw','quoteRaw','leadTimeRaw','quoteHeader','customQuoteRaw','customMoqRaw','customLeadTimeRaw','description','remarksRaw','sourceNote','materialRaw'];const cell=value=>csvCell(Array.isArray(value)?value.join('、'):txt(value));download('\ufeff'+[columns,...records.map(r=>columns.map(k=>r[k]))].map(row=>row.map(cell).join(',')).join('\r\n'),'源泽包材-产品资料.csv','text/csv;charset=utf-8');}

document.addEventListener('click',async event=>{const b=event.target.closest('button,a');if(!b||b.disabled)return;try{
  if(b.dataset.view){await navigate(b.dataset.view);return;}
  if(b.dataset.editRecord){openRecord(b.dataset.editRecord);return;}
  if(b.dataset.editSample){await openSample(b.dataset.editSample);return;}
  if(b.dataset.editPlan){openPlan(b.dataset.editPlan);return;}
  if(b.dataset.editUser){openUser(b.dataset.editUser);return;}
  if(b.dataset.editorTab){activateEditorTab(b.dataset.editorTab);return;}
  if(b.dataset.archive){b.disabled=true;try{await archiveItem(b.dataset.archive,b.dataset.id);}finally{b.disabled=false;}return;}
  if(b.dataset.history){await openHistory(b.dataset.history);return;}
  if(b.dataset.audit){openAudit(b.dataset.audit);return;}
  if(b.dataset.sampleEvents){await sampleEvents(b.dataset.sampleEvents);return;}
  if(b.dataset.restoreRevision){await restoreRevision(b.dataset.recordId,b.dataset.restoreRevision);return;}
  if(b.dataset.page!==undefined){goToPage(b.dataset.page);return;}
  if(b.dataset.detailOp){changeProductDetail(b);return;}
  if(b.dataset.imageOp){if(editor?.busy)return;const index=Number(b.dataset.index),op=b.dataset.imageOp;if(op==='remove'){if(!confirm('确定从本产品移除此图片吗？历史版本中的图片关联仍会保留。'))return;editor.images.splice(index,1);}else if(op==='first'){if(!canSetPrimary(editor.images[index],index))return;editor.images.unshift(editor.images.splice(index,1)[0]);}else{const next=index+(op==='up'?-1:1);if(next<0||next>=editor.images.length)return;[editor.images[index],editor.images[next]]=[editor.images[next],editor.images[index]];}editor.dirty=true;renderImages();return;}

  if(b.id==='logout'){if(!canDiscard())return;await api('/api/logout',{});state.mainDirty=false;if(editor)editor.dirty=false;location.href='/login';return;}
  switch(b.dataset.action){case 'retry-session':b.disabled=true;await init();break;case 'new-record':openRecord();break;case 'new-sample':await openSample();break;case 'new-user':openUser();break;case 'close-dialog':closeDialog();break;case 'retry':await navigate(state.view,true);break;case 'reset-filters':state.query='';state.showArchived=false;state.kind='';state.page=1;render();break;case 'reindex':b.disabled=true;await api('/api/admin/reindex',{});toast('已开始更新搜图索引，可继续处理其他资料。');await loadIndex();break;case 'export-csv':exportProducts('csv');break;case 'export-json':exportProducts('json');break;case 'clear-import':state.importPreview=null;state.importName='';render();break;case 'commit-import':await commitImport();break;}
}catch(error){toast(errorText(error));if(b.dataset.action==='reindex')b.disabled=false;}});
document.addEventListener('input',event=>{markDirty(event.target.form);updateProductDetail(event.target);if(event.target.dataset.imageField&&editor?.type==='record'){const i=editor.images[Number(event.target.dataset.index)];if(i){i[event.target.dataset.imageField]=event.target.type==='checkbox'?event.target.checked:event.target.value;editor.dirty=true;}}});
document.addEventListener('change',async event=>{const el=event.target;try{markDirty(el.form);updateProductDetail(el);if(el.form?.id==='sampleForm'&&el.name==='status')setSampleBorrowFields();if(el.id==='productImageFiles'){await uploadImages([...el.files]);return;}if(el.id==='importFile'){await previewImport(el.files[0]);return;}if(el.dataset.imageField&&editor?.type==='record'){const i=editor.images[Number(el.dataset.index)];if(i){i[el.dataset.imageField]=el.type==='checkbox'?el.checked:el.value;editor.dirty=true;if(el.dataset.imageField==='role')renderImages();}}}catch(error){toast(errorText(error));}});
document.addEventListener('submit',async event=>{const form=event.target;if(!['adminPageJumpForm','filterForm','auditFilter','recordForm','settingsForm','taxonomyForm','sampleForm','planForm','userForm'].includes(form.id))return;event.preventDefault();try{if(form.id==='adminPageJumpForm'){goToPage(form.elements.page.value,true);return;}if(form.id==='filterForm'){const d=new FormData(form);state.query=String(d.get('query')||'');state.kind=String(d.get('kind')||'');state.showArchived=d.has('showArchived');state.page=1;render();return;}if(form.id==='auditFilter'){const d=new FormData(form);state.query=String(d.get('query')||'');state.auditResource=String(d.get('resource')||'');state.page=1;render();return;}if(form.id==='recordForm')await saveRecord(form);else if(form.id==='settingsForm')await saveSingleton(form,'settings');else if(form.id==='taxonomyForm')await saveSingleton(form,'taxonomy');else if(form.id==='sampleForm')await saveSimple(form,'samples');else if(form.id==='planForm')await saveSimple(form,'plans');else if(form.id==='userForm')await saveSimple(form,'users');}catch(error){setFormError(form,error);}});
document.addEventListener('invalid',event=>{const panel=event.target.closest('[data-editor-panel]');if(panel?.hidden)activateEditorTab(panel.dataset.editorPanel);},true);
$('#adminDialog').addEventListener('cancel',event=>{event.preventDefault();closeDialog();});
window.addEventListener('beforeunload',event=>{if(state.mainDirty||editor?.dirty||editor?.busy||state.importBusy){event.preventDefault();event.returnValue='';}});
function openHashRecord(){if(!location.hash.startsWith('#records/'))return;let id;try{id=decodeURIComponent(location.hash.slice(9));}catch{return;}if(cache.records.some(r=>r.id===id))openRecord(id);else toast('未找到指定产品，可能已被移除或编号无效。');}
window.addEventListener('hashchange',async()=>{if(!location.hash.startsWith('#records/'))return;if(!canDiscard())return;if(state.view!=='records')await navigate('records',true);openHashRecord();});
async function init(){try{session=await api('/api/session');if(session.role!=='admin'){location.replace('/');return;}$('#account').textContent=(session.name||session.username||'管理员')+' · 管理员';$('#logout').hidden=!!session.local;await navigate('records',true);openHashRecord();}catch(error){if(error.status===401){location.replace('/login');return;}$('#main').innerHTML=`<div class="panel load-error"><h2>无法打开管理后台</h2><p class="sub">${esc(errorText(error))}</p><button type="button" class="btn primary" data-action="retry-session">重试</button> <a class="btn" href="/catalog">返回员工网站</a></div>`;}}
init();
